import{_ as t,o as n,c as o,a3 as s}from"./chunks/framework.BJY4yM9V.js";const g=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),a={name:"explanation/decisions.md"};function r(i,e,d,c,p,h){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite — the decisions that shape hypha, the alternatives rejected, and the consequence each carries. Full history lives in the ledgers: ADR-0001 in this repo&#39;s <code>project/adrs/</code> (the extraction), ADR-0091 in the peregrin ledger (the entity-plane contract), PL-005 in the org ledger (the extraction plan).</p><h2 id="substrate-over-sessions-adr-0091" tabindex="-1">Substrate over sessions (ADR-0091) <a class="header-anchor" href="#substrate-over-sessions-adr-0091" aria-label="Permalink to &quot;Substrate over sessions (ADR-0091)&quot;">​</a></h2><p><strong>Decision:</strong> the distributed layer is shaped around generic <code>Entity {id, kind, indexDoc, health}</code> values and namespaced ops — never around sessions or campaigns.</p><p><strong>Alternatives:</strong> keep the entity plane inside peregrin shaped around <code>sepia-session</code> (every new workload kind — CI jobs, sturn claims, cicada schedules — would fork the substrate); a workload-specific plane per integration (N sync/arbitration implementations to keep correct).</p><p><strong>Consequence:</strong> integrations plug in by implementing the entity contract in their own repo; the substrate stays kind-agnostic — no <code>sepia</code>/<code>campaign</code>/session types in these crates, enforced by review.</p><h2 id="snapshot-bytes-are-opaque-end-to-end" tabindex="-1">Snapshot bytes are opaque end-to-end <a class="header-anchor" href="#snapshot-bytes-are-opaque-end-to-end" aria-label="Permalink to &quot;Snapshot bytes are opaque end-to-end&quot;">​</a></h2><p><strong>Decision:</strong> <code>Snapshot {entity, ref, bytes}</code> — serialize on the owner, import on the target; hypha never parses the payload.</p><p><strong>Alternatives:</strong> a substrate-owned snapshot schema (every integration&#39;s state model becomes hypha&#39;s problem); references to external stores (transfer breaks when the store is unreachable or versioned differently).</p><p><strong>Consequence:</strong> migration semantics (<code>campaign-snapshot/v1</code>, sepia session IR) belong entirely to the integration — hypha guarantees transport, ordering, and arbitration, nothing more.</p><h2 id="ops-are-namespaced-and-ttl-d" tabindex="-1">Ops are namespaced and TTL&#39;d <a class="header-anchor" href="#ops-are-namespaced-and-ttl-d" aria-label="Permalink to &quot;Ops are namespaced and TTL&#39;d&quot;">​</a></h2><p><strong>Decision:</strong> op <code>kind</code> is <code>&lt;integration&gt;.&lt;verb&gt;</code> with <code>entity.*</code> reserved for the substrate; outbox entries carry idempotency keys and TTLs, and <code>Turn</code>-class ops dead-letter on first failure.</p><p><strong>Alternatives:</strong> a flat global verb namespace (collisions across integrations); infinite retries (a poisoned op blocks its entity&#39;s FIFO forever).</p><p><strong>Consequence:</strong> the substrate can route and dedupe without understanding any verb; a failing op surfaces as dead-letter instead of silent backlog.</p><h2 id="policy-is-injected-not-owned" tabindex="-1">Policy is injected, not owned <a class="header-anchor" href="#policy-is-injected-not-owned" aria-label="Permalink to &quot;Policy is injected, not owned&quot;">​</a></h2><p><strong>Decision:</strong> <code>hypha-control</code> is a pure arbitration library — lock registry, takeover, <code>pick_owner</code> — with no I/O; the hub boots an empty <code>KindPolicies</code> and integrations supply policy.</p><p><strong>Alternatives:</strong> policy baked into the hub (who-may-act rules become substrate concerns); policy in each node (split-brain arbitration).</p><p><strong>Consequence:</strong> arbitration is testable pure code; orchestration policy stays in peregrin where it belongs — the substrate decides <em>mechanism</em>, never <em>intent</em>.</p><h2 id="extracted-from-peregrin-composed-upward" tabindex="-1">Extracted from peregrin, composed upward <a class="header-anchor" href="#extracted-from-peregrin-composed-upward" aria-label="Permalink to &quot;Extracted from peregrin, composed upward&quot;">​</a></h2><p><strong>Decision:</strong> hypha is the entity plane lifted out of peregrin (PL-005); <code>peregrin-node</code> becomes a thin composition root that registers entity planes on a hypha node host.</p><p><strong>Alternatives:</strong> keep the plane inside peregrin (the substrate could never serve non-orchestration workloads); a ground-up rewrite (the wire shapes and outbox semantics were already proven in production inside peregrin).</p><p><strong>Consequence:</strong> dependency direction is one-way — <code>peregrin → hypha → ports</code>. Orchestration sits <em>on</em> the substrate; the substrate never imports orchestration.</p>',22)])])}const u=t(a,[["render",r]]);export{g as __pageData,u as default};
